#include <stdio.h>
#include <time.h>

int main(void) {
    struct tm tm = {0};
    sscanf("2024-06-15 09:30:00", "%d-%d-%d %d:%d:%d",
           &tm.tm_year, &tm.tm_mon, &tm.tm_mday,
           &tm.tm_hour, &tm.tm_min, &tm.tm_sec);
    tm.tm_year -= 1900; tm.tm_mon -= 1;
    time_t t = timegm(&tm);
    struct tm out;
    gmtime_r(&t, &out);
    char buf[64];
    strftime(buf, sizeof buf, "%Y-%m-%d %H:%M:%S +0000 UTC", &out);
    puts(buf);
    return 0;
}

#include <stdio.h>

int main(void) {
    puts("07/04/2024");
