}

#include <stdio.h>
#include <time.h>

int main(void) {
    struct tm tm = {0};
    tm.tm_year = 2024 - 1900; tm.tm_mon = 0; tm.tm_mday = 15;
    tm.tm_hour = 10;
    time_t t = timegm(&tm) + (3 * 24 + 5) * 3600;
    struct tm out;
    gmtime_r(&t, &out);
    char buf[64];
    strftime(buf, sizeof buf, "%Y-%m-%d %H:%M:%S +0000 UTC", &out);
    puts(buf);
    return 0;
}

