#include <stdio.h>
#include <time.h>

int main(void) {
    struct tm tm = {0};
    tm.tm_year = 2024 - 1900; tm.tm_mon = 5; tm.tm_mday = 1;
    tm.tm_hour = 10; tm.tm_min = 15; tm.tm_sec = 30;
    time_t t = timegm(&tm);
    struct tm out;
    gmtime_r(&t, &out);
    char buf[64];
    strftime(buf, sizeof buf, "%Y-%m-%d %H:%M:%S UTC", &out);
    puts(buf);
    printf("Hour: %d\n", out.tm_hour);
    printf("Minute: %d\n", out.tm_min);
    t += 1;
    gmtime_r(&t, &out);
    strftime(buf, sizeof buf, "%Y-%m-%d %H:%M:%S UTC", &out);
    printf("After +1s: %s\n", buf);
    return 0;
}
